import time
import logging
from taf.ue.tm500.asc.exception import AlreadyDisconnectedErr


class ASCSSHConnection:

    _BYTE_SIZE_PRE_RECV = 65535
    _WAITTING_INTERVAL_PRE_RECV = 0.1
    _PROMPT = r'ASC>'

    def __init__(self, ssh_connection):
        self._connection = ssh_connection
        if not self._connection.is_connected:
            raise AlreadyDisconnectedErr()
        self._channel = self._connection.invoke_shell()

    @property
    def ssh_connection(self):
        return self._connection

    def execute(self, command, execute_sleep=2, timeout=None):
        timeout = timeout or 10
        if self._channel.closed:
            logging.debug("old channel has been closed, invoke a new one")
            self._channel = self._connection.invoke_shell()

        self._read_until_end(self._channel, timeout=1)
        self._channel.send(command + '\n')
        time.sleep(execute_sleep)
        output = self._read_until_end(self._channel, timeout)
        return output

    def _read_until_end(self, channel, timeout):
        output = ''

        start_time = time.time()
        while (time.time() - float(start_time)) < timeout:
            if self._check_end_flag(output):
                break
            if channel.recv_ready():
                data = channel.recv(self._BYTE_SIZE_PRE_RECV)
                if isinstance(data, bytes):
                    part_msg = data.decode("utf-8", "ignore")
                else:
                    part_msg = data
                output += part_msg
            time.sleep(self._WAITTING_INTERVAL_PRE_RECV)

        return output

    @property
    def is_connected(self):
        return self._connection.is_connected

    def _check_end_flag(self, output):
        return self._PROMPT in output
